// ═══════════════════════════════════════════════════════════════════════
// 별의 방 콘텐츠 — 베다 점성술 나크샤트라 27개 · 라시 12개 · 다스리는 별 9개. 로직 없음.
// 화면 문구(버튼·제목)는 data.js의 TEXT.star
//
// 나크샤트라: 달이 하늘을 한 바퀴(약 27.3일) 도는 길을 27칸으로 나눈 '달의 집'. 순서는 계산 결과 번호(0~26)라 바꾸지 말 것.
// (N자 = 공백 포함 최대 글자 수)
//
//   code          코드용 이름. 바꾸지 말 것
//   name          캡처 카드 제목 (6자, 36px 한 줄) · 공유 카드 제목 · 후보 카드
//   sanskrit      캡처 카드 부제 로마자
//   title         집 이름 — 캡처 카드 부제 · 공유 카드 부제 (20자)
//   symbol / star / deity   첫째 장 사실 목록 값 (각 30자 권장. 넘으면 줄바꿈)
//   archetype     원형 태그 (warrior sage lover rebel caregiver explorer creator ruler). 27개를 8원형에 3~4개씩
//   archetypeWhy  결과 화면 "이 방에서 얻은 원형" 근거 한 줄 (60자)
//   key           캡처 카드 핵심 문장 + 공유 카드 본문 (60자, 3줄)
//   traits        둘째 장 "이거 완전 내 얘기?" 맞아요 3줄 (각 40자). 앞 2개는 후보 카드 공감 문장으로도 쓰임 (각 45자)
//   fact          결과 아래 문화 상식 카드 (150자)
//   identity      첫째 장(정체): title(목차 16자), lede = 첫 문단(강조, 80자) → 사실 목록 → body 단락들 → TEXT.star.result.interpretNote
//   event         둘째 장(사건): hook = 첫째 장 끝 떡밥(45자), title(목차 16자), lede(80자), body(첫 단락 뒤에 맞아요 인셋), quote(50자)
//   shadow        셋째 장(그림자): hook = 둘째 장 끝 떡밥, title, lede, body, quote
//   advice        넷째 장(다음): hook = 셋째 장 끝 떡밥, title, lede, body. 실행 가능한 긍정적 조언으로 끝낸다
//   summary       나의 이야기 2장 요약 (문단 배열, 합계 300~500자)
//   단락 하나는 250자 이하(권장 120~250). 분량 목표(기획서): 한 집 = 4,000~5,000자
// ═══════════════════════════════════════════════════════════════════════

